def encode(message):
    encoded_message = ''
    for char in message:
        if char.isalpha():
            index = ord(char) - ord('a') + 2
            if index > 26:
                index -= 26
            encoded_message += chr(ord('a') + index)
        else:
            encoded_message += char
    return encoded_message
