def do_algebra(operator, operand):
    # Check if the length of the operator list is equal to the length of the operand list minus one
    if len(operator) == len(operand) - 1:
        # Initialize result to the first element of the operand list
        result = operand[0]
        # Iterate through the operator and operand lists together
        for op, num in zip(operator, operand[1:]):
            # Perform the operation according to the current operator and add the result to the result
            if op == '+':
                result += num
            elif op == '-':
                result -= num
            elif op == '*':
                result *= num
            elif op == '/':
                result //= num
            elif op == '**':
                result **= num
        # Return the result of the expression
        return result
    else:
        # If the length of the operator list is not equal to the length of the operand list minus one, raise a ValueError
        raise ValueError("The length of the operator list must be equal to the length of the operand list minus one.")
