        return "NO"

    # Check if all elements of lst1 are even
    for i in range(len(lst1)):
        if lst1[i] % 2 != 0:
            break
    else:
        return "YES"

    # Check if all elements of lst2 are odd
    for i in range(len(lst2)):
        if lst2[i] % 2 == 0:
            break
    else:
        return "NO"

    # Exchange elements between lst1 and lst2
    for i in range(len(lst1)):
        if lst1[i] % 2 != 0 and lst2[i] % 2 == 0:
            tmp = lst1[i]
            lst1[i] = lst2[i]
            lst2[i] = tmp

    # Check if all elements of lst1 are even now
